/// Turns a `dlsym`/`eglGetProcAddress` result into an optional entry point.
///
/// # Safety
/// `p` must be null or a pointer to a function with `F`'s signature.
#[inline]
unsafe fn cast<F>(p: *const c_void) -> Option<F> {
    if p.is_null() {
        None
    } else {
        // transmute_copy, not transmute: the compiler cannot see that a thin
        // pointer and a bare `extern fn` pointer are the same size.
        Some(unsafe { std::mem::transmute_copy(&p) })
    }
}

#[inline]
fn need<F>(f: Option<F>, name: &'static str) -> F {
    f.unwrap_or_else(|| panic!("egl: entry point {name} is not loaded - the test did not check for what it needs"))
}
